from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
import os

def get_blob_service_client(account_url=None):
    account_url = account_url or os.environ.get("AZURE_STORAGE_ACCOUNT_URL")
    if not account_url:
        raise ValueError("Azure Storage Account URL not provided and not found in environment variables.")
    credential = DefaultAzureCredential()
    return BlobServiceClient(account_url, credential=credential)

def get_container_client(container_name, account_url=None):
    client = get_blob_service_client(account_url)
    return client.get_container_client(container_name)

def get_blob_client(container_name, blob_name, account_url=None):
    client = get_blob_service_client(account_url)
    return client.get_blob_client(container=container_name, blob=blob_name)

from storage_client import get_container_client
from storage_models import ConfigType, PayloadType

def list_prefix(payload: PayloadType, config: ConfigType = None) -> PayloadType:
    config = config or {}
    container_name = config.get("container_name", payload.get("container_name"))
    prefix = payload.get("prefix", "")
    max_results = payload.get("max_results")

    if not container_name:
        raise ValueError("Missing required parameter: container_name")

    container_client = get_container_client(container_name, config.get("account_url"))

    blob_list = []
    for blob in container_client.list_blobs(name_starts_with=prefix):
        blob_list.append({
            "name": blob.name,
            "size": blob.size,
            "last_modified": blob.last_modified.isoformat() if blob.last_modified else None,
            "creation_time": blob.creation_time.isoformat() if blob.creation_time else None,
            "content_settings_content_type": blob.content_settings.content_type,
        })
        if max_results and len(blob_list) >= max_results:
            break

    return {"objects": blob_list}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential
from storage_client import get_blob_client
from storage_models import ConfigType, PayloadType
import os

def stored_document_ocr(payload: PayloadType, config: ConfigType = None) -> PayloadType:
    config = config or {}
    # Azure AI Vision endpoint and key from config or environment variables
    endpoint = config.get("azure_vision_endpoint", os.environ.get("AZURE_VISION_ENDPOINT"))
    key = config.get("azure_vision_key", os.environ.get("AZURE_VISION_KEY"))
    container_name = config.get("container_name", payload.get("container_name"))
    object_name = payload["object_name"]

    if not all([endpoint, key, container_name, object_name]):
        raise ValueError("Missing required parameters: Azure Vision endpoint, key, container name, object name.")

    # Construct the URL for the blob
    account_url = config.get("account_url", os.environ.get("AZURE_STORAGE_ACCOUNT_URL"))
    if not account_url:
        raise ValueError("Azure Storage Account URL not provided and not found in environment variables.")
    blob_url = f"{account_url}/{container_name}/{object_name}"

    # Authenticate and create client
    credential = AzureKeyCredential(key)
    client = ImageAnalysisClient(endpoint=endpoint, credential=credential)

    # Perform OCR
    # Using `features=[VisualFeatures.READ]` for OCR
    # The SDK will download the image from the URL provided.
    try:
        result = client.analyze_from_url(image_url=blob_url, visual_features=[VisualFeatures.READ])
    except Exception as e:
        return {"error": f"Azure AI Vision OCR failed: {str(e)}"}

    extracted_text = []
    if result.read and result.read.blocks:
        for block in result.read.blocks:
            for line in block.lines:
                extracted_text.append(line.text)

    return {"extracted_text": "\n".join(extracted_text)}

from azure.ai.translation.text import TextTranslationClient, TranslatorCredential
from azure.ai.translation.text.models import InputTextItem
from storage_models import ConfigType, PayloadType
import os

def stored_text_translate(payload: PayloadType, config: ConfigType = None) -> PayloadType:
    config = config or {}
    # Azure Translator endpoint and key from config or environment variables
    endpoint = config.get("azure_translator_endpoint", os.environ.get("AZURE_TRANSLATOR_ENDPOINT"))
    key = config.get("azure_translator_key", os.environ.get("AZURE_TRANSLATOR_KEY"))

    source_text = payload["text"]
    target_language = payload.get("target_language", "en") # Default to English

    if not all([endpoint, key, source_text]):
        raise ValueError("Missing required parameters: Azure Translator endpoint, key, source text.")

    # Authenticate and create client
    credential = TranslatorCredential(key, endpoint)
    client = TextTranslationClient(endpoint=endpoint, credential=credential)

    # Perform translation
    try:
        # The `translate` method expects a list of InputTextItem objects
        response = client.translate(target_language=target_language, content=[InputTextItem(text=source_text)])
    except Exception as e:
        return {"error": f"Azure AI Translator failed: {str(e)}"}

    translated_text = []
    if response:
        for translation_result in response:
            if translation_result.translations:
                for translation in translation_result.translations:
                    translated_text.append(translation.text)

    return {"translated_text": "\n".join(translated_text)}
